window.FULL_DOCUMENT_2 = {"id":"doc-2","title":"Инструкция по автоклавной обработке кирпича-сырца","source":"_______________________________________________________________1.docx","blocks":[{"type":"text","text":"ОГЛАВЛЕНИЕ"},{"type":"text","text":"Основные понятиястр. 2"},{"type":"text","text":"АСУ автоклавной обработки кирпича сырцастр. 3"},{"type":"text","text":"Характеристика объекта управлениястр. 3"},{"type":"text","text":"Основные этапы технологического цикла автоклавной обработкистр. 3"},{"type":"text","text":"Состав системы управлениястр. 3"},{"type":"text","text":"Система управления автоклавамистр. 4"},{"type":"text","text":"Топология сети автоматической системы управления (АСУ) стр. 5"},{"type":"text","text":"интерфейс SCADA-системыстр. 5"},{"type":"text","text":"Идентификация операторастр. 5"},{"type":"text","text":"Отображение информации на главном экране системыстр. 6"},{"type":"text","text":"Подробная информация о каждом автоклавестр. 6"},{"type":"text","text":"Трендыстр. 8"},{"type":"text","text":"Журнал событийстр. 12"},{"type":"text","text":"управление автоклавомстр. 13"},{"type":"text","text":"Управление крышкамистр. 13"},{"type":"text","text":"Режим перепускастр. 14"},{"type":"text","text":"инструкция по технологической панели операторастр. 15"},{"type":"text","text":"Общее описаниестр. 15"},{"type":"text","text":"Настройка контроллеров стр. 21"},{"type":"text","text":"Основной экран контроллера стр. 22"},{"type":"text","text":"Меню контроллерастр. 23"},{"type":"text","text":"Вкладка «настройка циклограмм»стр. 24"},{"type":"text","text":"Основной экран контроллерастр. 25"},{"type":"text","text":"Система вакуумного насосастр. 26"},{"type":"text","text":"Возможные неисправности подсистемы управления крышками"},{"type":"text","text":"и методы их устранениястр. 28"},{"type":"text","text":"Возможные неисправности подсистемы вакуумного насоса стр. 30"},{"type":"text","text":"Возможные неисправности подсистемы автоклавной обработки стр. 31"},{"type":"text","text":"Метод пропуска ошибок без останова процессастр. 32"},{"type":"text","text":"Основные сведения о процессе автоклавной обработки стр. 32"},{"type":"text","text":"Предотвращение «провалов» в циклограммах при запаривании кирпичастр. 33"},{"type":"text","text":"Действия обслуживающего персонала при отказе системы автоматического управления автоклавной обработкой «Sсada».стр. 34"},{"type":"text","text":"Чистка автоклава и замена уплотнительной резиновой прокладкистр. 35"},{"type":"text","text":"Техническое описание и принцип работы автоклава стр. 36"},{"type":"text","text":"Шкаф управления крышками автоклава стр. 39"},{"type":"text","text":"Шкаф управления автоклавной обработкойстр. 41"},{"type":"text","text":"Перепуски из автоклавовстр. 44"},{"type":"text","text":"Шкаф управления вакуумным насосом стр. 45"},{"type":"text","text":"Шкафы управления насосными станциямистр. 47"},{"type":"text","text":"Шкафы управления конденсатными насосамистр. 48"},{"type":"text","text":"Расположение и название клапанов с электроприводамистр. 51"},{"type":"text","text":"Запаривание цветного, лицевого и рядового кирпичастр. 52"},{"type":"text","text":"Запаривание рядового кирпичастр. 52"},{"type":"text","text":"Запаривание цветного, лицевого кирпичастр. 53"},{"type":"text","text":"Конденсатная линия автоклавастр. 54"},{"type":"text","text":"Обязанности операторастр. 54"},{"type":"text","text":"ОСНОВНЫЕ ПОНЯТИЯ"},{"type":"text","text":"SCADA (Supervisory Control And Data Acquisition) – диспетчерское управление и сбор данных."},{"type":"text","text":"Основные задачи, решаемые SCADA-системой:"},{"type":"text","text":"Обмен данными между контроллером в реальном времени;"},{"type":"text","text":"Управление АСУ;"},{"type":"text","text":"Обработка информации в реальном времени;"},{"type":"text","text":"Отображение информации на экране монитора в понятной для человека форме;"},{"type":"text","text":"Ведение базы данных реального времени с технологической информацией;"},{"type":"text","text":"Аварийная сигнализация и управление тревожными сообщениями;"},{"type":"text","text":"Подготовка и генерирование отчетов о ходе технологического процесса."},{"type":"text","text":"АРМ (автоматизированное рабочее место) – программно-технический комплекс, предназначенный для автоматизации деятельности определенного вида. АРМ объединяет программно-аппаратные средства, обеспечивающие взаимодействие человека с компьютером, предоставляет возможность ввода и вывода информации."},{"type":"text","text":"АСУ – комплекс аппаратных и программных средств, предназначенный для управления различными процессами в рамках технологического процесса, производства, предприятия."},{"type":"text","text":"Контроллер – управляющее устройство, применяемое в промышленности и других отраслях по условию применения и задачам. Применяется для автоматизации технологических процессов."},{"type":"text","text":"Панель HMI – компактная вычислительная машина со встроенным жидкокристаллическим дисплеем, предназначенная для визуализации параметров процесса (объекта) и осуществления операторского управления. Панель HMI является элементом построения человеко-машинного интерфейса систем управления. Для реализации функций управления панели снабжаются блоками кнопочного управления и(или) сенсорными экранами."},{"type":"text","text":"Датчик – термин систем управления, первичный преобразователь, элемент измерительного, сигнального, регулирующего или управляющего устройства системы, преобразующий контролируемую величину в удобный для использования сигнал."},{"type":"text","text":"АСУ АВТОКЛАВНОЙ ОБРАБОТКИ КИРПИЧА СЫРЦА"},{"type":"text","text":"Характеристика объекта управления"},{"type":"text","text":"Объектами управления являются проходные автоклавы в количестве 8 штук. Для управления подачей и сбросом пара, а также для управления сбросом конденсата автоклавы оснащены запорно- регулирующей арматурой. Автоклавы оснащены быстросъемными крышками с затворами байонетного типа. Управление открыванием и закрыванием крышек осуществляется при помощи гидроцилиндров. Положение механизмов крышек контролируется путевыми конечными выключателями. Автоклавы оснащены штатными сигнально-блокировочными устройствами (СБУ), которые обеспечивают фиксацию крышек автоклавов в закрытом положении."},{"type":"text","text":"Для управления крышками автоклавов и гидростанцией применяются ящики управления. Для подачи давления от гидростанции только к управляемому автоклаву используются гидрораспределители с электромагнитным управлением. Рабочее давление в автоклаве до 1,2 Мпа, температура до 203°С."},{"type":"text","text":"Технологический процесс автоклавной обработки изделий является циклическим процессом с длительностью цикла до 20 часов."},{"type":"text","text":"Основные этапы технологического цикла автоклавной обработки:"},{"type":"text","text":"загрузка автоклава;"},{"type":"text","text":"закрытие крышки автоклава;"},{"type":"text","text":"вакуумирование;"},{"type":"text","text":"предварительный прогрев;"},{"type":"text","text":"поднятие давления и температуры в автоклаве;"},{"type":"text","text":"выдержка изделий при заданном давлении заданное время;"},{"type":"text","text":"сброс давления;"},{"type":"text","text":"открывание крышки;"},{"type":"text","text":"выгрузка готовых изделий из автоклава."},{"type":"text","text":"Состав системы управления"},{"type":"text","text":"Система управления предназначена для управления автоклавами и состоит из двух систем:"},{"type":"text","text":"Система управления крышками автоклава, включающая в себя:"},{"type":"text","text":"ящик управления механизмами крышки;"},{"type":"text","text":"ящик управления гидростанцией;"},{"type":"text","text":"путевые конечные выключатели (комплектно с автоклавом) для контроля положения"},{"type":"text","text":"механизмы крышки;"},{"type":"text","text":"гидрораспределители с электромагнитнымприводомдляуправления гидроцилиндрами;"},{"type":"text","text":"гидрораспределители с электромагнитнымприводомдлявыбора соответствующего автоклава."},{"type":"text","text":"Система управления автоклавной обработкой, включающая в себя:"},{"type":"text","text":"ящик управления автоклавной обработкой;"},{"type":"text","text":"ящик управления вакуумным насосом;"},{"type":"text","text":"ящик коммуникаций;"},{"type":"text","text":"датчики давления и температуры (установлены на автоклавах и магистрали острого пара)."},{"type":"text","text":"Система управления автоклавами"},{"type":"text","text":"Система разработана с применением контроллеров фирмы Segnetics типа SMH-2GI. Разработанная система относится к распределенным системам управления. В системе можно выделить два уровня в иерархии управления. Нижний уровень управления включает в себя систему автоматизации автоклава, систему управления насосной станцией и систему вакуумирования. На нижнем уровне реализовано оперативное управление оборудованием с помощью технологических панелей операторов, кнопок и переключателей соответствующих ящиков управления. Ящики управления размещены в непосредственной близости от технологического оборудования для сокращения длины проводов и кабелей. Второй уровень — это уровень, объединяющий вышеперечисленные системы нижнего уровня автоматизации на уровне Scada-системы. Система управления автоклавом функционально состоит из подсистемы управления крышками автоклавов и подсистемы управления автоклавной обработкой."},{"type":"text","text":"Подсистема управления крышками"},{"type":"text","text":"Состоит из двух ящиков управления крышками (по одному на крышку). Подсистема выполнена с применением контроллеров SMH 2Gi. Подсистема предусматривает местный автоматический, местный ручной и наладочный режимы управления. Наладочный режим включается снятием соответствующей перемычки в электрической схеме ящика управления. Каждый ящик оснащен «ключ маркой» (установлена стоповая кнопка с ключом). Все программные блокировки безопасности продублированы электрическими блокировками цепей управления электромагнитами гидроприводов крышки. Ящики установлены в непосредственной близости от крышек автоклава. Подсистема управления крышками электрически связана с ящиком управления гидростанции и подсистемой управления автоклавной обработки."},{"type":"text","text":"Система управления гидростанцией"},{"type":"text","text":"Система управления гидростанцией включает в себя ящик управления и панель с электромагнитными гидрораспределителями. Система предусматривает ручной и автоматический режимы управления. Система обеспечивает управление основным и резервным насосами, а также управляет гидрораспределителями выбора автоклава. Давление масла будет подаваться только на тот автоклав, на котором осуществляется управление крышкой."},{"type":"text","text":"Подсистема управления автоклавной обработкой"},{"type":"text","text":"В систему управления автоклавной обработки входят: ящик управления автоклавной обработкой (установлен на площадке в зоне обслуживания, в непосредственной близости от запорно-регулирующей арматуры автоклава), электроприводы запорно-регулирующей арматуры, датчики температуры и давления. Подсистема выполнена с применением контролера SMH 2Gi и сенсорной панели оператора Weintek МТ8100. Подсистема предусматривает как автоматический, так и ручной режим управления. Подсистема оснащена кнопкой аварийного отключения с ключом. При нажатии на кнопку остановки происходит включение электроприводов клапанов подачи пара на закрытие. Ручное управление запорно-регулирующими клапанами реализовано с технологической панели оператора. На панель выводится информация о состоянии автоклава:"},{"type":"text","text":"тренд давления;"},{"type":"text","text":"тренд температуры среды внутри автоклава;"},{"type":"text","text":"тренды температур верхней и нижней образующих автоклава;"},{"type":"text","text":"состояния запорно-регулирующей арматуры;"},{"type":"text","text":"состояния крышек автоклава;"},{"type":"text","text":"параметры технологического цикла автоклавной обработки (заданное давление и температура, участок цикла, время цикла;"},{"type":"text","text":"меню задания технологических параметров."},{"type":"text","text":"Подробное описание функций технологической панели оператора описано в инструкции на панель оператора. Подсистема электрически (блокировки безопасности) по интерфейсной связи связана с подсистемой управления крышками."},{"type":"text","text":"Система управления вакуумированием"},{"type":"text","text":"В состав системы входят: ящик управления (установлен рядом с вакуумным насосом), соленоидные клапаны. Кроме того, к ящику управления подключаются магистральные датчики температуры и давления острого пара, данные с которых посредством интерфейсной линии связи поступают в системы управления автоклавной обработкой и в систему верхнего уровня. Система управления вакуумированием выполнена на базе контролера SMH 2Gi. Система предусматривает автоматический и ручной режимы управления. Запуск насоса осуществляется посредством контактора, а защита посредством мотор-автомата. В автоматическом режиме предусмотрены блокировки по условиям пуска насоса. При пуске насоса предусмотрена задержка пуска двигателя насоса для заполнения камеры насоса водой."},{"type":"text","text":"Система второго уровня"},{"type":"text","text":"В состав системы входит ящик коммуникаций, установленный в помещении оператора и персональный компьютер со SCADA системой. Подробнее о АРМ описано в инструкции."},{"type":"text","text":"Топология сети автоматической системы управления (АСУ)"},{"type":"text","text":"АСУ является распределённой. Она состоит из двух уровней:"},{"type":"text","text":"Ящики управления;"},{"type":"text","text":"ПК со Scada системой."},{"type":"text","text":"Сеть построена на технологии Ethernet. В системах управления автоклавной обработкой обмен между панелью оператора и контроллером ведётся по интерфейсу RS-485, протокол Modbus."},{"type":"text","text":"ИНТЕРФЕЙС SCADA-СИСТЕМЫ"},{"type":"text","text":"Идентификация оператора"},{"type":"text","text":"Для предотвращения несанкционированного управление системой введены права доступа."},{"type":"text","text":"При входе в программу, система потребует идентификации. Необходимо выбрать требуемого пользователя и ввести пароль (рисунок 3.1). Пароли выдаются только операторам."},{"type":"image","src":"images/doc2_000.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.1 – Окно идентификации оператора"},{"type":"text","text":"После окончания смены необходимо выйти из системы, для этого необходимо нажать кнопку в верхнем левом углу главного экрана."},{"type":"text","text":"Отображение информации на главном экране системы"},{"type":"text","text":"Для лучшего отображения информации на главном экране изображено 8 автоклавов. Для каждого автоклава регистрируются в реальном масштабе времени показания датчиков температур верхней и нижней образующей, температуры внутри автоклава, давления в автоклаве, состояния запорно-регулирующей арматуры, состояния крышек автоклавов, а также краткое информационное окно, в котором регистрируется состояние автоклава и этап цикла запаривания. Для подробной информации каждого автоклава по отдельности необходимо нажать кнопку «Управление», находящуюся к информационном окне (рисунок 3.2)."},{"type":"image","src":"images/doc2_001.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.2 – Главный экран scada-системы"},{"type":"text","text":"Подробная информация о каждом автоклаве."},{"type":"text","text":"При нажатии на кнопку «Управление» происходит переход на окно мнемосхемы отдельно выбранного автоклава (рисунок 3.3). В данном окне отображаются показания датчиков положения регулирующих клапанов, состояния путевых концевых выключателей крышек автоклава, состояния запорно-регулирующей арматуры (рисунок 3.4), а также информации о системе, состоящей из:"},{"type":"text","text":"статуса сигнально-блокировочных устройств;"},{"type":"text","text":"«под давлением» (в автоклаве есть давление, работа с крышками запрещена);"},{"type":"text","text":"«без давления» (в автоклаве нет давления, работа с крышками разрешена)."},{"type":"text","text":"статуса системы в целом;"},{"type":"text","text":"«автоклав не готов к запариванию» – крышки автоклава открыты;"},{"type":"text","text":"«автоклав готов к запариванию» – все крышки закрыты и зафиксированы (СБУ введены);"},{"type":"text","text":"«цикл запаривания запущен» – началось запаривание сырца;"},{"type":"text","text":"«авария» – система перешла в режим останова, для более подробной информации необходимо перейти в журнал событий;"},{"type":"text","text":"«предупреждение» – система продолжает цикл запаривания, для более подробной информации необходимо перейти в журнал событий;"},{"type":"text","text":"«нажата кнопка СТОП» – на щите автоклавной обработки нажата кнопка стоп;"},{"type":"text","text":"«цикл запаривания закончен» – цикл закончен."},{"type":"text","text":"этапа запаривания;"},{"type":"text","text":"«ожидание» – система ожидает сигнала на управление;"},{"type":"text","text":"«инициализация» – первоначальный этап запаривания, все клапаны закрываются;"},{"type":"text","text":"«вакуумирование» – второй этап, при котором начинается откачивание воздуха из автоклава;"},{"type":"text","text":"«регулирование» – третий этап запаривания, начинается подача пара в автоклав и регулирование по циклограмме;"},{"type":"text","text":"«сброс пара» – четвёртый этап запаривания, при котором начинается сброс пара из автоклава по заданной циклограмме;"},{"type":"text","text":"оставшегося времени цикла;"},{"type":"text","text":"режима подачи пара;"},{"type":"text","text":"«острый пар» – пар подаётся из котельной;"},{"type":"text","text":"«с перепуском» – пар подаётся из автоклава-источника."},{"type":"text","text":"режима сброса пара;"},{"type":"text","text":"«в атмосферу» – пар сбрасывается в атмосферу;"},{"type":"text","text":"«в перепуск» – пар сбрасывается в автоклав-приёмник."},{"type":"text","text":"режима работы;"},{"type":"text","text":"«автоматический» – переключатель в положении автоматический режим;"},{"type":"text","text":"«ручной» – переключатель ключом переведён в ручной режим. Управление только с панели;"},{"type":"text","text":"режима управления:"},{"type":"text","text":"«НM1» – управление переведено на панель оператора;"},{"type":"text","text":"«Scada» – управление переведено на персональный компьютер."},{"type":"image","src":"images/doc2_002.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.3 – Мнемосхема отдельно выбранного автоклава"},{"type":"image","src":"images/doc2_003.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.4 – Состояние запорной аппаратуры"},{"type":"text","text":"Тренды"},{"type":"text","text":"Для визуализации графиков зависимости параметров от времени, используется окно «тренд», которое позволяет не только просматривать эти графики, но и анализировать их. На рисунке 3.5 приведён пример тренда с отображением двух параметров"},{"type":"image","src":"images/doc2_004.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.5 – Пример тренда, с отображением двух параметров"},{"type":"text","text":"Управление видимостью панелей. Окно тренда состоит из нескольких функциональных панелей:"},{"type":"text","text":"окно графиков. Служит для отображения графических объектов-перьев, элементов разметки, средств анализа;"},{"type":"text","text":"таблица значений. Служит для отображения данных в табличном виде;"},{"type":"text","text":"панель легенды. Служит для хранения и управления списками объектов тренда."},{"type":"text","text":"Во избежание загромождения пользовательского интерфейса предусмотрена возможность управления видимостью панелей (разрешить или запретить видимость панели на экране). Управление видимостью панелей тренда производится из панели управления тренда при помощи кнопок с фиксацией (рисунок 3.6)."},{"type":"image","src":"images/doc2_005.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.6 – Панель управления тренда"},{"type":"text","text":"Работа с перьями. Перо является базовым понятием MasterSCADA. Перо – это график, с которым связана переменная MasterSCADA из дерева объектов. Активное перо является ключевым понятием тренда. На тренде одновременно может находиться несколько перьев и у каждого, может быть, своя вертикальная шкала и масштаб отображения. Горизонтальные оси всех графиков совмещены и их границы совпадают с интервалом на панели даты-времени. В каждый момент времени может быть активным только одно перо, именно его шкала отображается на вертикальной оси по умолчанию. Активным перо можно сделать следующими способами:"},{"type":"text","text":"выбрать перо в окне графиков кликом мыши по геометрии графика;"},{"type":"text","text":"выбрать перо в панели перьев кликом мыши по названию пера;"},{"type":"text","text":"выбрать перо в минилегенде кликом мыши по названию пера;"},{"type":"text","text":"Активное перо подсвечивается утолщением графика, а также подсветкой в панели перьев и минилегенде. По умолчанию вертикальная ось принимает цвет активного пера, а разметка координатной сетки подгоняется так, чтобы значения активного пера были округлёнными. Активное перо является текущим выбранным графическим объектом и его свойства отображаются в панели настроек."},{"type":"text","text":"Масштабирование перьев. Масштабирование перьев – это операция сжатия или растягивания графиков данных по оси значений. Масштабирование применяется к выделенному графику (если ни один график не выделен, то масштабируются все). Выделенный график масштабируется при помощи элементов управления вертикальными границами."},{"type":"text","text":"Управление масштабом времени. Изменение масштаба времени происходит одновременно для всех элементов тренда. Управление масштабом времени может происходить следующими способами:"},{"type":"text","text":"а) При помощи горизонтального навигатора (рисунок 3.7). Составными частями горизонтального навигатора являются:"},{"type":"text","text":"кнопка перехода к самому первому событию/значению за всю историю;"},{"type":"text","text":"кнопка сдвига временного окна к более ранним данным на 1%;"},{"type":"text","text":"кнопка сдвига временного окна к более ранним данным на 10%;"},{"type":"text","text":"кнопка изменения левой границы окна (граница ползунка);"},{"type":"text","text":"ползунок сдвига временного окна;"},{"type":"text","text":"кнопка изменения правой границы окна (граница ползунка);"},{"type":"text","text":"кнопка сдвига временного окна к более поздним данным на 10%;"},{"type":"text","text":"кнопка сдвига временного окна к более поздним данным на 1%;"},{"type":"text","text":"кнопка перехода к самому последнему событию/значению за всю историю;"},{"type":"image","src":"images/doc2_006.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.7 – Горизонтальный навигатор"},{"type":"text","text":"б)Посредством панели даты/времени, которая содержит следующие элементы слева направо:"},{"type":"text","text":"элемент календарь для выбора даты левой границы;"},{"type":"text","text":"элемент время для выбора левой границы;"},{"type":"text","text":"кнопка управления автопрокруткой. Переключает режим автопрокрутки;"},{"type":"text","text":"элемент быстрого выбора интервалов времени;"},{"type":"text","text":"кнопка загрузки сохранённого состояния тренда (состояния, сохранённого в режимеразработки);"},{"type":"text","text":"кнопки возврата временного состояния RT, после загрузки сохранённого состояния тренда;"},{"type":"text","text":"элемент календарь для выбора даты правой границы;"},{"type":"text","text":"элемент время для выбора правой границы."},{"type":"text","text":"в) Прокруткой колеса мыши при нахождении курсора в окне графиков осуществляет изменение масштаба времени окна графиков."},{"type":"text","text":"Также при изменении масштаба времени большую роль играет панель выбора слоёв данных. Слои данных – это заданные интервалы прореживания данных. За счёт использования слоёв при просмотре истории на больших интервалах времени из архива выбирается значительно меньший (на порядки) объём данных, что снижает загрузку процессора и ускоряет работу тренда при просмотре архивов. Например, при просмотре архива за месяц из архива выбираются не все данные, а прореженные данные за час (четыре значения за сутки: первое, максимальное, минимальное, последнее). Слои данных выбираются автоматически, однако есть возможность просмотреть данные в определённом слое при помощи панели выбора слоёв данных. Непрореженный слой отображает непрореженные данные. Временный слой отображает данные, ещё не помещённые в архив (например, при использовании отдельного архивного сервера, если с ним пропала связь)."},{"type":"text","text":"Режим автопрокрутки. Режим автопрокрутки предназначен для того, чтобы в режиме исполнения отображать на экране не всегда самые актуальные данные. При включенном режиме автопрокрутки текущее время и соответственно данные всегда находятся в области видимости. В режиме автопрокрутки происходит отключение некоторых визуальных элементов, например, задания даты/времени и кнопок навигации по маркерам. То, какие именно элементы отключаются, зависит от текущего уровня сложности тренда. Режим автопрокрутки переключается кнопкой автопрокрутки на панели даты-времени."},{"type":"text","text":"Работа с панелью перьев. Панель перьев (рисунок 3.8) предназначена для отображения списков перьев и информации по ним. Панель перьев может отображать разный объём информации:"},{"type":"text","text":"признак видимости пера;"},{"type":"text","text":"кнопка вызова диалога редактирования внешнего вида пера. Кнопка окрашена в цвет линии пера;"},{"type":"text","text":"название пера. При клике мыши возможно редактирование названия;"},{"type":"text","text":"текущие границы вертикального масштаба. При клике мыши возможно редактирование границ;"},{"type":"text","text":"размерность пера (наследуется из шкалы параметра);"},{"type":"text","text":"значение пера в срезе вертикального курсора."},{"type":"text","text":"При клике мыши на строку с пером выбранное перо становится активным пером. При наведении мыши на строку с пером – оно подсвечивается в окне графиков."},{"type":"image","src":"images/doc2_007.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.8 – Панель перьев"},{"type":"text","text":"Работа с минилегендой. Минилегенда отображает список перьев (рисунок 3.9). В отличие от панели перьев этот список максимально упрощён. Минилегенда отображает цвет пера, его название и последнее значение. Минилегенда может находиться в развёрнутом или в свёрнутом (рисунок 3.10) состоянии, чтобы не мешать просмотру."},{"type":"image","src":"images/doc2_008.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.9 – Минилегенда в развернутом состоянии"},{"type":"image","src":"images/doc2_009.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.10 – Минилегенда в свернутом состоянии"},{"type":"text","text":"Свёртывание/развёртывание минилегенды осуществляется кликом мыши по шапке легенды.По умолчанию в минилегенде отображаются в панели перьев, но отображение отдельных перьев вминилегенде можно запретить из панели перьев. При клике мыши на строку с пером - выбранное перо становится активным пером. При наведении мыши на строку с пером оно подсвечивается в окне графиков."},{"type":"text","text":"Отображение данных в табличном виде. В тренде есть возможность отображения данных в табличном виде. Для этого предназначена таблица значений. Таблица значений отображает данные графиков, видимость которых включена в легенде."},{"type":"text","text":"Для таблицы значений, возможно, использование интерполяции данных, для этого следует нажать на кнопку «режим интерполяции», после чего в таблице будут отображаться интерполированные данные (вычисленные промежуточные значения между значениями, поступившими от источника)."},{"type":"text","text":"Сохранение снимков экрана. Сохранение снимков экрана производится в диалоговом окне снимков (рисунок 3.11):"},{"type":"text","text":"кнопка «Формат» задаёт формат графического файла для сохранения;"},{"type":"text","text":"кнопка «Ширина» задаёт разрешение снимка по высоте;"},{"type":"text","text":"кнопка «Файл» задаёт место на диске для сохранения снимка;"},{"type":"text","text":"кнопка «Обновить» производит обновление зоны предварительного просмотра;"},{"type":"text","text":"кнопка «Сохранить» сохраняет снимок в файл с заданными параметрами."},{"type":"image","src":"images/doc2_010.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.11 – Сохранения снимка графика"},{"type":"text","text":"Журнал событий"},{"type":"text","text":"Журнал предназначен для отображения сообщений в табличном виде (рисунок 3.12). Таблица сообщений служит для отображения списка сообщений в табличном виде. Не квитированные сообщения (сообщения, прочтение которых оператор не квитировал, то есть не подтвердил) отображаются курсивом."},{"type":"image","src":"images/doc2_011.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 3.12 – Журнал событий"},{"type":"text","text":"Отчёты"},{"type":"text","text":"Для регистрации циклов запаривания в Scada-системе предусмотрена автоматическая генерация отчётов после каждого цикла запаривания."},{"type":"text","text":"УПРАВЛЕНИЕ АВТОКЛАВОМ"},{"type":"text","text":"Управление крышками"},{"type":"text","text":"Этапы закрытия крышки:"},{"type":"text","text":"Убедиться в том, что около крышек нет людей, ничто не мешает закрытию крышки (вагонетки, масляные шланги, прокладки и т.д.);"},{"type":"text","text":"На щите управления требуемой крышки вставить ключ и поворотом ключа отжать кнопку «СТОП»;"},{"type":"text","text":"Перевести в требуемый режим подсистему (ручной/автоматический);"},{"type":"text","text":"Если система переведена в автоматический режим, то нажать кнопку «ЦИКЛ ЗАКРЫТИЯ КРЫШКИ», если в ручной последовательно нажимать кнопки управления гидроцилиндрами (опустить мостик – закрыть крышку – повернуть байонет);"},{"type":"text","text":"Вставить штырь сигнально-блокировочного устройства в байонетный затвор и закрыть вентиль проверки остаточного давления;"},{"type":"text","text":"Убедиться в том, что пришел сигнал о закрытии крышки (на щите управления должна загореться лампочка «крышка закрыта и зафиксирована»)."},{"type":"text","text":"4.1.2 Этапы открытия крышки:"},{"type":"text","text":"Убедиться в том, что все клапаны подачи и сброса пара закрыты, кнопка «СТОП» отжата, штырь СБУ выдернут. Если все эти условия выполнены должен погаснуть красный индикатор на контроллере."},{"type":"text","text":"Перевести в требуемый режим подсистему (ручной/автоматический);"},{"type":"text","text":"Если система переведена в автоматический режим, то нажать кнопку «ЦИКЛ ОТКРЫТИЯ КРЫШКИ», если в ручной последовательно нажимать кнопки управления гидроцилиндрами (повернуть байонет – открыть крышку – поднять мостик)."},{"type":"text","text":"Этапы управления циклом запаривания:"},{"type":"text","text":"Убедиться в том, что закрыты и зафиксированы крышки, при это на экране компьютера в информационном окне должен поменяться статус на «Автоклав готов к запариванию»;"},{"type":"text","text":"Перевести управление в автоматический режим, для этого необходимо перевести переключатель режима в положение «Авто»;"},{"type":"text","text":"Переключиться на режим управления с APM (SCADA), для этого необходимо последовательно нажать кнопку «не выбрано Scada hmi» в информационном окне автоклава;"},{"type":"text","text":"Нажать кнопку на панели управления scada, при этом появится окно управления автоклавом (рисунок 4.1);"},{"type":"image","src":"images/doc2_012.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"В появившемся окне выбрать циклограмму (для изменения выбранной циклограммы нажать кнопку изменить). После того так выбрали циклограммы, нажмите кнопку «ОК» для подтверждения выбора;"},{"type":"image","src":"images/doc2_013.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 4.1 – Окно управления автоклавом"},{"type":"text","text":"ВНИМАНИЕ!"},{"type":"image","src":"images/doc2_014.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Пока не выбрана циклограмма, дальнейшее управление запрещено. Для отмены выбора циклограммы нажмите «Отмена»"},{"type":"text","text":"Выбрать источник пара (из котельной или из автоклава-источника). Подтвердите выбор, нажав кнопку «ОК»."},{"type":"text","text":"ВНИМАНИЕ!"},{"type":"text","text":"Для перехода к выбору циклограммы необходимо нажать «Отмена», при этом выбранный источник аннулируется. Пока не выбран источник, дальнейшее управление запрещено."},{"type":"image","src":"images/doc2_015.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Нажать кнопку «ПУСК/СТОП»"},{"type":"text","text":"ВНИМАНИЕ!"},{"type":"image","src":"images/doc2_016.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Как только запустился цикл запаривания какие-либо изменения в циклограмме или выборе другого источника пара ЗАПРЕЩЕНЫ."},{"type":"text","text":"После того как оставшееся время станет равным 0, и в информационном окне в строке этап поменяется на «ожидание», необходимо выбрать путь сброса пара (в атмосферу, либо в автоклав-приёмник) и подтвердить выбор."},{"type":"text","text":"Режим перепуска"},{"type":"text","text":"При данном режиме экономится пар из котельной. В автоклав (автоклав-приёмник), в котором начинается цикл запаривания при данном режиме, пар поступает из другого автоклава (автоклав- источник). Как только давления в обоих автоклавах выровняются, в автоклав-приёмник пар будет поступать из котельной, а оставшийся пар в автоклаве-источнике будет сбрасываться в атмосферу."},{"type":"text","text":"Включение данного режима:"},{"type":"text","text":"В автоклаве-источнике при выборе сброса пара необходимо выбрать «в перепуск» и подтвердить выбор. После данной операции откроется клапан сброса пара на перепуск и автоклав- источник будет ожидать момента выравнивания давления."},{"type":"text","text":"В автоклаве-приёмнике при выборе источника пара необходимо выбрать «с перепуском» и подтвердить выбор."},{"type":"text","text":"ВНИМАНИЕ!"},{"type":"text","text":"Цикл запаривания с перепуском в автоклаве-приёмнике необходимо начинать только после того, как откроется клапан сброса пара на перепуск в автоклаве-источнике."},{"type":"image","src":"images/doc2_017.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"ИНСТРУКЦИЯ ПО ТЕХНОЛОГИЧЕСКОЙ ПАНЕЛИ ОПЕРАТОРА"},{"type":"text","text":"Общее описание"},{"type":"text","text":"Панель оператора служит для управления и анализа системы управления автоклавной обработки кирпича-сырца."},{"type":"text","text":"Управление и анализ системы для удобства в панели разбит по вкладкам. Для переходов по вкладкам необходимо нажать кнопку «МЕНЮ» в левом верхнем углу. Всё управление разбито на четыре вкладки: главный экран, управление, тренды и журнал."},{"type":"text","text":"Вкладка «Главный экран»"},{"type":"text","text":"На рисунке 5.1 представлен главный экран системы управления."},{"type":"image","src":"images/doc2_018.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 5.1 – Общий вид главного экрана системы"},{"type":"text","text":"Исполнительные механизмы"},{"type":"text","text":"На рисунке 5.2 – мнемосхема автоклава с описанием клапанов, на рисунке 5.3 представлены состояния клапанов."},{"type":"text","text":"Цифрами на мнемосхеме автоклава указаны:"},{"type":"text","text":"1 – клапан подпора (подача пара под прокладку);"},{"type":"text","text":"2 – клапан сброса подпора (сброс пара из-под прокладки в автоклав);"},{"type":"text","text":"3 – клапан острого пара (подача острого пара в автоклав из котельной);"},{"type":"text","text":"4 – клапан перепуска (подача пара в автоклав из перепускной магистрали);"},{"type":"text","text":"5 – клапан конденсата (открытие продувочной конденсатной линии);"},{"type":"text","text":"6 – клапан сброса пара в атмосферу (сброс пара из автоклава в атмосферу);"},{"type":"text","text":"7 – клапан вакуумирования (открытие магистрали вакуумирования);"},{"type":"text","text":"8 – клапан перепуска (сброс пара из автоклава в перепускную магистраль)."},{"type":"image","src":"images/doc2_019.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 5.1 – Мнемосхема автоклава"},{"type":"image","src":"images/doc2_020.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 5.3 – Состояние клапанов"},{"type":"text","text":"Положение регулирующих клапанов"},{"type":"text","text":"Для визуализации положения клапанов существуют графы и значение открытия в процентном соотношении. На рисунке 5.4 представлены графы положения регулирующих клапанов."},{"type":"image","src":"images/doc2_021.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 5.4 – Графы положения регулирующих клапанов"},{"type":"text","text":"Показания датчиков"},{"type":"text","text":"В системе датчики выполняют функцию сбора информации, а именно температуры верхней составляющей, температуру нижней составляющей, температуры внутри автоклава, температуры в магистрали, давление в магистрали и давление в автоклаве. Пример показания датчика внутри автоклава показан на рисунке 5.5."},{"type":"image","src":"images/doc2_022.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 5.5 – Показания датчика внутри автоклава"},{"type":"text","text":"Информационное окно системы"},{"type":"text","text":"В информационном окне, представленном на рисунке 5.6, выводится:"},{"type":"text","text":"Статус (всей системы):"},{"type":"text","text":"автоклав не готов к запариванию – крышки автоклава открыты;"},{"type":"text","text":"автоклав готов к запариванию – все крышки закрыты и зафиксированы;"},{"type":"text","text":"цикл запаривания запущен – началось запаривание сырца;"},{"type":"text","text":"авария – система перешла в режим останова, для более подробной информации необходимо перейти в журнал событий;"},{"type":"text","text":"предупреждение – система продолжает цикл запаривания, для более подробной информации необходимо перейти в журнал событий;"},{"type":"text","text":"нажата кнопка «СТОП» – на щите автоклавной обработки нажата кнопка стоп;"},{"type":"text","text":"цикл запаривания закончен – цикл закончен."},{"type":"image","src":"images/doc2_023.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 5.6 – Информационное окно системы"},{"type":"text","text":"Этап:"},{"type":"text","text":"ожидание – система ожидает сигнала на управление;"},{"type":"text","text":"инициализация – первоначальный этап запаривания, все клапаны закрываются;"},{"type":"text","text":"вакуумирование – второй этап, при котором начинается откачивание воздуха из автоклава;"},{"type":"text","text":"регулирование – третий этап запаривания, начинается подача пара в автоклав и регулирование по циклограмме;"},{"type":"text","text":"сброс пара – четвертый этап запаривания, при котором начинается сброс пара из автоклава по заданной циклограмме."},{"type":"text","text":"Управление:"},{"type":"text","text":"HMI – включено управление с панели, управление с компьютера запрещено;"},{"type":"text","text":"компьютер – включено управление с компьютера, управление с панели запрещено;"},{"type":"text","text":"не выбрано – доступ к управлению закрыт."},{"type":"text","text":"Оставшееся время – приблизительное время, через которое регулирование, либо сброс пара, в зависимости от этапа, закончится."},{"type":"text","text":"Вкладка «Управление»"},{"type":"text","text":"На рисунке 5.7 представлено окно управления автоклавом в автоматическом режиме. Запуск системы осуществляется в следующем порядке:"},{"type":"text","text":"Убедиться, что включено управление с панели (необходимо выбрать в информационном окне);"},{"type":"text","text":"Убедиться, что все крышки закрыты и зафиксированы;"},{"type":"text","text":"Выбрать соответствующую циклограмму. Все параметры выбранной циклограммы приведены в левой половине экрана;"},{"type":"image","src":"images/doc2_024.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 5.7 – Вкладка управление"},{"type":"text","text":"Выбрать и подтвердить источник пара:"},{"type":"text","text":"острый пар – пар берётся из котельной;"},{"type":"text","text":"перепуск – пар берётся из автоклава-источника."},{"type":"text","text":"Нажать кнопку «ПУСК», при этом она поменяет цвет на зелёный;"},{"type":"text","text":"После этапа регулирования необходимо выбрать и подтвердить, куда осуществлять сброс пара из автоклава:"},{"type":"text","text":"в атмосферу – пар из автоклава будет сбрасываться в атмосферу;"},{"type":"text","text":"в перепуск – пар будет сбрасываться в автоклав-приёмник."},{"type":"text","text":"После того как в информационном окне в статусе будет написано «Этап запаривания закончен», убедиться, что все клапаны закрыты, СБУ открыто и отжата кнопка стоп, при этом должна погаснуть красная лампочка на контроллере управления крышками и только после этого открывать крышки."},{"type":"text","text":"На рисунке 5.8 представлено окно ручного управления автоклавом. Чтобы перейти в данный режим необходимо переключить переключатель режима на щите управления в положение «Ручн». В данном режиме управление с компьютера блокируется."},{"type":"image","src":"images/doc2_025.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 5.8 – Ручное управление автоклавом"},{"type":"text","text":"В ручном режиме, чтобы открыть/закрыть какой-либо клапан, необходимо нажать на соответствующую кнопку (рисунок 5.9)."},{"type":"image","src":"images/doc2_026.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 5.9 – Открытие/закрытие клапана"},{"type":"text","text":"ВНИМАНИЕ!"},{"type":"image","src":"images/doc2_027.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Одновременно можно управлять только ОДНИМ клапаном."},{"type":"text","text":"Вкладка «Журнал»"},{"type":"text","text":"На рисунке 5.10 показано окно журнала событий. В данной вкладке регистрируются все случаи, которые происходили с системой."},{"type":"image","src":"images/doc2_028.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 5.10 – Журнал событий"},{"type":"text","text":"Вкладка «Тренды»"},{"type":"text","text":"В данной вкладке находятся графики показаний датчиков. Данные архивируются. Для выбора требуемого графика необходимо нажать одну из кнопок в верхней части экрана, к примеру «Давление» (рисунок 5.11)."},{"type":"image","src":"images/doc2_029.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рисунок 5.11 – График давления"},{"type":"text","text":"Доступ"},{"type":"text","text":"Для предотвращения несанкционированного изменения каких-либо параметров системы, а также защиты от включения системы людьми, не имеющими полномочия на это, введены несколько пользователей."},{"type":"text","text":"Для входа в систему оператором или старшим оператором, необходимо нажать кнопку «доступ» на экране «вкладки» главного экрана. Появится окно выбора пользователя и пароль. Рис. 5.12."},{"type":"image","src":"images/doc2_030.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Классы доступа:"},{"type":"text","text":"1. Класс доступа «0» (не выбран)"},{"type":"text","text":"Пользователь может посмотреть состояние системы управления на эеране."},{"type":"text","text":"2. Класс доступа «А»"},{"type":"text","text":"С такими правами пользователь может запустить цикл запаривания, посмотреть журнал, тренды, а также имеет все права класса доступа «0»."},{"type":"text","text":"3. Класс доступа «В» (ст. оператор)"},{"type":"text","text":"С такими правами пользователь имеет полный доступ к управлению с панели системой, а именно ручной ввод циклограммы, ручное управление системой, а также все права класса допуска «А»."},{"type":"text","text":"Вход в систему"},{"type":"text","text":"Для входа в систему необходимо выбрать пользователя: оператор – класс доступа «А», старший оператор – класс доступа «В», и ввести пароль."},{"type":"text","text":"Внимание! После работы необходимо нажать кнопку «смена пользователя» и выключить управление с панели. Это необходимо для того, чтобы сбросить класс доступа до «0». Пароли выдаются только обслуживающему персоналу."},{"type":"text","text":"Настройка контроллеров"},{"type":"image","src":"images/doc2_031.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Для сбора информации, а также управления системой в щите управления автоклавной обработкой установлен контроллер Segnetics SMH 2Gi. Рис. 6.1."},{"type":"image","src":"images/doc2_032.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Управление контроллера:"},{"type":"text","text":"1. «Stop» - клавиша сброса аварии. Для сброса необходимо нажать и удерживать в течение 5 сек."},{"type":"text","text":"2. «Enter» - клавиша для подтверждения операции"},{"type":"text","text":"3. «Escape» - клавиша для возврата в предыдущее меню"},{"type":"text","text":"4. «стрелочки» - клавиши навигации по экрану контроллера"},{"type":"text","text":"5. клавиатура – для ввода цифровых значений"},{"type":"text","text":"Основной экран контроллера"},{"type":"text","text":"На рис. 6.2 изображён основной экран контроллера."},{"type":"image","src":"images/doc2_033.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Статус (Статус системы):"},{"type":"text","text":"«Останов» - система остановлена;"},{"type":"text","text":"«Инициализация» - возврат всех клапанов подачи и сброса пара в исходное (закрытое) состояние;"},{"type":"text","text":"«Вакуумирование»-1 этап цикла запаривания;"},{"type":"text","text":"«Регулирование»- 2 этап цикла запаривания;"},{"type":"text","text":"«Сброс пара»- 3 этап цикла запаривания"},{"type":"text","text":"Показания датчиков:"},{"type":"text","text":"«Верх» - температура верхней образующей автоклава;"},{"type":"text","text":"«Низ» - температура нижней образующей;"},{"type":"text","text":"«Внутр.» - температура среды внутри автоклава;"},{"type":"text","text":"«Давление» - давление в автоклаве."},{"type":"text","text":"Положение регулирующих клапанов:"},{"type":"text","text":"«Острого пара» - положение клапана подачи острого пара из магистрали;"},{"type":"text","text":"«Перепуска» - положение клапана подачи пара из перепускной магистрали;"},{"type":"text","text":"«Сброса пара» - положение клапана сброса пара в атмосферу."},{"type":"text","text":"Меню контроллера"},{"type":"text","text":"На рис. 6.3 изображено меню контроллера."},{"type":"image","src":"images/doc2_034.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"В основном меню контроллера имеются четыре вкладки:"},{"type":"text","text":"Настройки;"},{"type":"text","text":"Журнал;"},{"type":"text","text":"Настройка циклограмм;"},{"type":"text","text":"Ручной ввод циклограммы;"},{"type":"text","text":"Вкладка «настройка циклограмм»"},{"type":"text","text":"На рис. 6.5 изображена вкладка «настройка циклограмм»"},{"type":"image","src":"images/doc2_035.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Во вкладке настраиваются циклограммы цикла запаривания. Вход в данный пункт меню находится под паролем. Пароли выдаются только обученному обслуживающему персоналу. Пример настройки циклограмм приводится ниже в таблице."},{"type":"text","text":"Таблица 6.2 - Пример настройки циклограммы №1."},{"type":"text","text":"Вкладка «ручной ввод циклограмм»"},{"type":"text","text":"В данной вкладке можно ввести параметры циклограмм для режима ручного ввода (рис. 6.6). Данное действие также можно осуществить с панели оператора."},{"type":"image","src":"images/doc2_036.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Так же на контроллере расположены светодиодные индикаторы, рис.6.8"},{"type":"image","src":"images/doc2_037.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Индикатор №1 - Блокировка открытия крышки. Индикатор светится в следующих случаях:"},{"type":"text","text":"Штырь СБУ введен в ответную часть;"},{"type":"text","text":"Нажата кнопка «Стоп»;"},{"type":"text","text":"«Пришел сигнал с СБУ - Автоклав под давлением;"},{"type":"text","text":"Пришел сигнал блокировки из ящика управления автоклавной обработкой (клапаны подачи и сброса пара находятся в открытом положении, автоклав под давлением)."},{"type":"text","text":"Индикатор №2 — Индикатор светится, когда в ящик управления гидростанцией оправлен сигнал на включение насоса."},{"type":"text","text":"Индикатор №3 - Индикатор светится, когда крышка опущена и сработал конечный выключатель положения «Крышка закрыта»."},{"type":"text","text":"Индикатор №4 - Светится, когда из ящика управления автоклавной обработкой пришел сигнал разрешения открытия крышки."},{"type":"text","text":"Основной экран контроллера"},{"type":"image","src":"images/doc2_038.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Статус (Статус системы):"},{"type":"text","text":"«Останов» - система остановлена;"},{"type":"text","text":"«Пуск насоса» - Запуск насоса гидростанции;"},{"type":"text","text":"«Авария» - произошёл отказ одно из устройств (залипание конечных выключателей и т.п.), работа невозможна;"},{"type":"text","text":"«Пусконаладка» - Наладочный режим;"},{"type":"text","text":"«Открытие» - Запущен автоматический цикл открытия крышки;"},{"type":"text","text":"«Закрытие» - Запущен автоматический цикл закрытия крышки;"},{"type":"text","text":"Режим работы:"},{"type":"text","text":"Автоматический (активированы кнопки цикла открытия/закрытия крышки);"},{"type":"text","text":"Ручной (активированы кнопки ручного открытия/закрытия системы);"},{"type":"text","text":"Система вакуумного насоса"},{"type":"text","text":"Для сбора информации, а также управления системой в ящике управления вакуумным насосом установлен контроллер SEGNETICS SMH 2Gi (рисунок 6.13)"},{"type":"text","text":"1. F1 – клавиша входа в меню контроллера"},{"type":"image","src":"images/doc2_039.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"2. F3 – клавиша входа в меню событий"},{"type":"text","text":"3. Stop – клавиша сброса аварии. Для сброса необходимо нажать и удерживать в течение 5 секунд"},{"type":"text","text":"4. Enter – клавиша для подтверждения операции"},{"type":"text","text":"5. Escape – клавиша возврата в предыдущее меню"},{"type":"text","text":"6. Стрелки – клавиши навигации по экрану контроллера"},{"type":"text","text":"7. Клавиатура – для ввода числовых значений"},{"type":"text","text":"Основной экран контроллера"},{"type":"text","text":"На рис. 6.14 показан основной экран контроллера"},{"type":"image","src":"images/doc2_040.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Статус (Статус системы):л"},{"type":"text","text":"«Останов» - система остановлена;"},{"type":"text","text":"«Запуск» - происходит последовательность запуска системы;"},{"type":"text","text":"«Работа» - Запущен этап вакуумирования;"},{"type":"text","text":"«Авария» - произошёл отказ одного из устройств;"},{"type":"text","text":"«Стоп» - Нажата кнопка стоп;"},{"type":"text","text":"«Слив» - этап окончания вакуумирования, при котором сливается вода из вакуумного насоса;"},{"type":"text","text":"Вакуумирование (какой автоклав сейчас вакуумируется)"},{"type":"text","text":"Давление в автоклаве;"},{"type":"text","text":"Режим:"},{"type":"text","text":"Ручной (запуск вакуумного насоса производится с ящика управления вакуумным насосом);"},{"type":"text","text":"Автоматический (запуск производится по интерфейсной линии связи с ящика управления автоклавной обработкой);"},{"type":"text","text":"Аварийная ситуацияАварийная ситуацияОбрыв связи с автоклавомОбрыв связи с автоклавомГрафическое отображение:"},{"type":"image","src":"images/doc2_041.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc2_042.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Меню контроллера"},{"type":"text","text":"На рис. 6.15 изображено меню контроллера"},{"type":"image","src":"images/doc2_043.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"1. Вкладка настройки параметров."},{"type":"text","text":"Во вкладке «настройки» находятся все параметры настройки системы, необходимые для работы. Вход в данный пункт меню защищён паролем. Пароли выдаются только обученному обслуживающему персоналу."},{"type":"text","text":"Возможные неисправности подсистемы управления крышками и методы их устранения"},{"type":"text","text":"Для того чтобы сбросить аварию нажмите и удерживайте 5 секунд кнопку «СТОП» на контроллере. При аварийной ситуации замигает индикатор «АВАРИЯ» на щите управления крышкой."},{"type":"text","text":"Возможные неисправности подсистемы вакуумного насоса"},{"type":"text","text":"Для того чтобы сбросить аварию нажмите и удерживайте 5 секунд кнопку «СТОП» на контроллере. При аварийной ситуации замигает индикатор «АВАРИЯ» на ящике управления вакуумным насосом."},{"type":"text","text":"Возможные неисправности подсистемы автоклавной обработки"},{"type":"text","text":"Для того чтобы сбросить аварию нажмите и удерживайте 5 секунд кнопку «СТОП» на контроллере. При аварийной ситуации замигает индикатор «АВАРИЯ» на ящике управления."},{"type":"text","text":"Метод пропуска ошибок без останова процесса"},{"type":"text","text":"В некоторых случаях, к примеру, не сработал концевой выключатель клапана, можно продолжить работу. При появлении аварии на экране АРМ появится окно предупреждения, при этом оператору необходимо визуально убедиться в том, что клапан закрыт, после чего нажать кнопку «продолжить» в появившемся окне на панели оператора."},{"type":"text","text":"Основные сведения о процессе автоклавной обработки."},{"type":"text","text":"Автоклавная обработка – завершающая операция производства силикатного кирпича. Чтобы придать кирпичу-сырцу необходимую прочность, его подвергают гидротермальной обработке в среде насыщенного пара при температуре 174,5-203 градусов и давлении соответственно 0,8-1,6 Мпа. На нашем предприятии кирпич-сырец выдерживается при давлении 1,2 Мпа. На скорость и структуру образования гидросиликатов кальция в кирпиче оказывают влияние растворимость и дисперсность компонентов известково-кремнеземистой смеси, а также режим автоклавной обработки (температуры и давления). В процессе автоклавной обработки кирпича-сырца различают три периода химического процесса: растворение компонентов, кристаллизация и твердение."},{"type":"text","text":"Растворение компонентов: начинается с момента впуска пара в автоклав и плавного подъёма температуры до 174,5-203 градусов. При этом обрабатываемое изделие приобретает температуру, равную температуре теплоносителя – пара. В первый период за счёт температуры, давления, собственной влаги и влаги конденсированного пара, проникающего в поры изделия по капиллярам, происходит процесс растворения гидроксида кальция и других растворимых веществ, входящих в состав смеси. Насыщенный пар позволяет сохранить влагу в кирпиче-сырце, необходимую для растворения компонентов. Процесс растворения протекает по-разному. Растворимость гидроксида кальция понижается с повышением температуры, в то время как растворимость кремнезёма с повышением температуры повышается. При достижении температуры порядка 150 градусов начинает интенсивно растворяться кремнезём, что способствует образованию кремниевой кислоты. С появлением достаточного количества этой кислоты начинается интенсивная реакция нейтрализации с образованием в основном двухосновных гидросиликатов кальция."},{"type":"text","text":"Кристаллизация: начинается с достижения максимальной температуры в автоклаве и продолжается на протяжении всего изотермического процесса, т.е. обработки изделия при постоянных температуре и давлении. В этот период наиболее интенсивно протекает реакция образования гидросиликатов кальция и раствор становится насыщенным. Образовавшиеся в первую очередь двухосновные гидросиликаты кальция вступают во взаимодействие с продолжающей растворяться кремниевой кислотой, преобразуясь в низкоосновные гидросиликаты кальция. При насыщении раствора гидросиликаты кальция находятся сначала в коллоидном состоянии, затем по мере испарения влаги выкристаллизовываются и превращаются в твёрдые кристаллы. Важную роль играет равномерная подача пара для поддержания постоянной температуры и давления в автоклаве. Перепады давления вызывают сдвиг реакции в ту или иную сторону, нарушая процесс образования низкоосновных гидросиликатов кальция, которые влияют на прочность структуры силикатных бетонов."},{"type":"text","text":"Твердение: начинается с прекращения подачи пара в автоклав, падения давления и температуры до момента выгрузки изделий из автоклава. Период характеризуется завершением кристаллизации и по мере испарения жидкой фазы приобретением прочности образовавшихся гидросиликатов кальция. В этот момент важно обеспечить равномерно ускоренный выпуск пара из автоклава, что способствует испарению оставшейся влаги в изделии. Таким образом упрочняется изделие."},{"type":"text","text":"Предотвращение «провалов» в циклограммах"},{"type":"text","text":"при запаривании кирпича."},{"type":"text","text":"При запаривании кирпича с острого пара необходимо предварительно, на всех автоклавах, находящихся в работе в горизонтальном положении циклограммы открыть вручную запорно-регулирующие клапана «сброс пара из-под прокладки» на 50% и поднять давление в автоклавах до 12,5атм, при этом, все запорно- регулирующиеся клапана на остром паре закроются в автоматическом режиме, т.к. они настроены на 12атм, после чего, в щитах управления автоклавами, которые работали на горизонте циклограммы, отключить питание электроприводов всех клапанов выключением эл. автоматов QF-3 и QF-4 и затем запускаем нужный автоклав с острого пара. Отслеживаем давление пара в работающих автоклавах. При наборе давления в запариваемом автоклаве до 4,8атм, включаем в щитах управления автоклавами все отключенные эл. автоматы, закрываем вручную запорно-регулирующие клапана «сброс пара из-под прокладки», после чего система автоклавирования будет работать в автоматическом режиме. В случае падения давления на автоклавах, работающих на горизонте циклограммы, поддерживаем давление запорно-регулирующим клапаном «сброс пара из-под прокладки» вручную."},{"type":"text","text":"При запаривании кирпича с перепуском пара из отработавшего автоклава «источник», при наборе давления в запариваемом автоклаве «потребитель» 2,4атм, на всех автоклавах, находящихся в работе на горизонтальном положении циклограммы открыть вручную запорно-регулирующие клапана «сброс пара из-под прокладки» на 50% и поднять давление в автоклавах до 12,5атм, при этом, все запорно- регулирующиеся клапана на остром паре закроются в автоматическом режиме, т.к. они настроены на 12атм, после чего, в щитах управления автоклавами, которые работали на горизонте циклограммы, отключить питание электроприводов всех клапанов выключением эл. автоматов QF-3 и QF-4. Отслеживаем давление пара в работающих автоклавах. При наборе давления в запариваемом автоклаве до 4,8атм, включаем в щитах управления автоклавами все отключенные эл. автоматы, закрываем вручную запорно-регулирующие клапана «сброс пара из-под прокладки», после чего система автоклавирования будет работать в автоматическом режиме. В случае падения давления на автоклавах, работающих на горизонте циклограммы, поддерживаем давление запорно-регулирующим клапаном «сброс пара из-под прокладки» вручную."},{"type":"text","text":"Действия"},{"type":"text","text":"обслуживающего персонала при отказе системы автоматического управления автоклавной обработкой «Sсada»."},{"type":"text","text":"Признаки неисправности: при работе автоклавов на мониторе компьютера и на панели оператора не прописываются и не изменяются параметры давления температуры, уставки циклограммы в режиме реального времени набора, регулирования или сброса давления автоклава (программа «зависла»). Клапана подпора под прокладку пара и подачи острого пара закрыты."},{"type":"text","text":"Действия персонала:"},{"type":"text","text":"Выключить в щите управления автоматические выключатели управления электромагнитными клапанами QF – 3, QF – 4;"},{"type":"text","text":"На контроллере щита управления в меню «Ручной ввод циклограмм» при режиме регулирования автоклава (12 атм.) вводятся следующие параметры:"},{"type":"text","text":"- Р подъема, кПа – 100"},{"type":"text","text":"- t подъема, мин – 1"},{"type":"text","text":"- Р набора, кПа – 1215"},{"type":"text","text":"- t набора, мин – 1"},{"type":"text","text":"- t регулирования, мин – 360, в зависимости от оставшегося времени поддержания давления."},{"type":"text","text":"- t выдержки, мин – 1"},{"type":"text","text":"- t сброса, мин – 90"},{"type":"text","text":"- t сброса перепуск, мин – 40"},{"type":"text","text":"В режиме набора давления. Поднять давление до «горизонта» (12 атм.) в ручном режиме далее действия как при режиме регулирования давления автоклава."},{"type":"text","text":"В режиме сброса пара ввести следующие параметры:"},{"type":"text","text":"- Р подъема, кПа –100"},{"type":"text","text":"- t подъема, мин – 1"},{"type":"text","text":"- Р набора, кПа – 1215"},{"type":"text","text":"- t набора, мин – 1"},{"type":"text","text":"- t регулирования, мин – 1"},{"type":"text","text":"- t выдержки, мин – 1"},{"type":"text","text":"- t сброса, мин – 90"},{"type":"text","text":"- t сброса перепуск, мин – 40"},{"type":"text","text":"Выключить основной выключатель щита управления;"},{"type":"text","text":"Через 1 мин. включить основной выключатель щита управления."},{"type":"text","text":"Запустить цикл запаривания"},{"type":"text","text":"При достижении необходимого давления на мониторе компьютера включить управление «Scada» на щите управления режим «авто»;"},{"type":"text","text":"В щите управления включить автоматические выключатели QF – 3, QF – 4;"},{"type":"text","text":"В окне управления на мониторе компьютера выбрать циклограмму «подбор параметров» нажать кнопку «ок»;"},{"type":"text","text":"В окне «набор давления» выбрать «острый пар» нажать кнопку «ок»;"},{"type":"text","text":"В окне запуск системы «пуск/стоп» выбрать «перезапуск системы» нажать кнопку «пуск»."},{"type":"text","text":"После вышеперечисленных действий система должна работать в автоматическом режиме."},{"type":"text","text":"Чистка автоклава и замена уплотнительной резиновой прокладки."},{"type":"text","text":"После каждого цикла запарки необходимо производить очистку автоклава от обвалившегося обрабатываемого материала», прочистка автоклава производится следующим образом:"},{"type":"text","text":"1.Освободить автоклав от запаренного кирпича."},{"type":"text","text":"2. Дать остыть автоклаву до температуры 1000С и открыть заднюю крышку автоклава в ручном режиме, не поднимая мостик, чтобы автоклав проветривался --температуру контролировать на дисплее контроллера управления автоклавом по «верхней составляющей»"},{"type":"text","text":"3. Дать остыть внутреннему пространству воздуха до 800С и приступить к прочистке автоклава—температуру контролировать по «нижней составляющей»"},{"type":"text","text":"4. С помощью метлы, скребка и лопаты совковой очищаются стенки и днище автоклава от налипшей смеси обрабатываемого материала и удаляется счищенная смесь в отходы."},{"type":"text","text":"5. Затем вынимается крышка—фильтр (две штуки) из отверстий в днище автоклава для непрерывного отвода конденсата и производится очистка данных крышек от налипшей смеси обрабатываемого материала с помощью щётки по металлу, а закупоренные отверстия с помощью прямого и крючкообразного шильев диаметром 3мм. Также очищать пригоревшую графитную смазку на крышке и на автоклавах. Вычищенная налипшая смесь так же удаляется в отходы.   Прочистка автоклавов производится по утверждённому графику после каждого запаривания (с росписью) и обязательна к исполнению."},{"type":"text","text":"Установка резиновой прокладки между крышкой автоклава и корпусом автоклава производится по мере износа прокладки всей или части её, предварительно замерив длину заменяемой износившейся прокладки. Износ прокладки определяют визуально – вынимают прокладку из паза автоклава, изгибают прокладку вверх «ласточкиным хвостом» и осматривают прокладку на наличие трещин, разрывов, уменьшение толщины прокладки из-за спекания резины и принимают решение о замене всей прокладки «если износ составляет 50% и более», или частично. Прокладку устанавливают без натяга, с запасом по длине. Количество вставок должно быть не более ОДНОЙ.  Соединение делать необходимо в нижней части паза автоклава с косым срезом конца прокладки для лучшей герметизации. Перед установкой прокладки в паз, необходимо удалить запёкшуюся графитовую смазку с сопрягаемых частей крышки автоклава и корпуса автоклава. После установки прокладки вновь смазать сопрягаемые части крышки и корпуса автоклава графитовой смазкой для предотвращения «задиров» на прокладке и сопрягаемых частях автоклава. Проверка прокладок осуществляется после каждой запарки со стороны загрузки и выгрузки! Так же оператор сам проверяет отверстие выхода пара под прокладку на забитость в ночное и дневное время. В случае, если отверстие забито в ночное время, оператор сам чистит его специальным приспособлением. Если забито в дневное, то зовёт слесаря."},{"type":"text","text":"Техническое описание и принцип работы автоклава."},{"type":"text","text":"Назначение: автоклав предназначен для термовлажностной обработки в среде насыщенного водяного пара силикатного кирпича и мелких блоков из ячеистых бетонов. Автоклавы устанавливаются на вновь проектируемых заводах силикатного кирпича, а также на реконструируемых действующих заводах в закрытых помещениях с температурой окружающей среды не ниже +5 градусов. Загрузка автоклава – 16 вагонеток."},{"type":"text","text":"Основные параметры: на заводе применяются автоклавы типа АП 1,2-2*19."},{"type":"text","text":"АП - автоклав проходной"},{"type":"text","text":"1,2 – рабочее давление 1,2 Мпа"},{"type":"text","text":"2 – внутренний диаметр корпуса, мм – 2000"},{"type":"text","text":"19 – длина рабочей части корпуса без крышек, мм – 19000"},{"type":"text","text":"Рабочий объём, м. куб – 60"},{"type":"text","text":"Рабочая температура, град. – 191"},{"type":"text","text":"Рабочее давление пара, Мпа – 1,2"},{"type":"text","text":"Гидравлическое давление при испытании, Мпа – 1,65"},{"type":"text","text":"Тип привода крышек – гидравлический"},{"type":"text","text":"Рабочее давление, Мпа – 12,0"},{"type":"text","text":"Также бывают автоклавы тупиковые (АТ), т.е. имеется всего одна крышка. Также различается длина рабочей части. Например: АП 1,2-2*19, АТ 1,2-2*19, АП 1,2-2*17, АТ 1,2-2*17."},{"type":"text","text":"Состав: Автоклав – это горизонтальный цилиндрический сосуд с открывающимися гидравлическим приводом торцевыми крышками, соединёнными с корпусом байонетным затвором."},{"type":"text","text":"Корпус с рельсовым путём"},{"type":"text","text":"Две крышки"},{"type":"text","text":"Механизм открывания, закрывания, поворота крышек и фиксации крышек в поднятом положении"},{"type":"text","text":"Комплект гидроцилиндров"},{"type":"text","text":"Гидросистема автоклава (с насосной станцией)"},{"type":"text","text":"Подавтоклавные опоры"},{"type":"text","text":"Ролики с противоугонным устройством для подвижных опор"},{"type":"text","text":"Реперное устройство"},{"type":"text","text":"Предохранительный клапан и два манометра"},{"type":"text","text":"Сигнально-блокировочное устройство (СБУ) – 2 шт."},{"type":"text","text":"Ключ-марка"},{"type":"text","text":"Элементы системы непрерывного отвода конденсата"},{"type":"text","text":"Перекидной мостик"},{"type":"text","text":"Электрооборудование автоклава, состоящее из шкафа управления крышками(2шт), шкафа управления процессом запаривания, шкафа управления маслостанцией."},{"type":"text","text":"Датчики контроля давления, температуры внутри автоклава и разности температур верхней и нижней образующих корпуса автоклава."},{"type":"text","text":"Устройство и работа составных частей:"},{"type":"text","text":"Корпус состоит из сваренных между собой трёх обечаек и двух фланцев. Фланцы являются элементом байонетного соединения корпуса с крышками. В торце фланца корпуса выполнена проточка, в которую входит уплотняющая резиновая прокладка. К корпусу привариваются подвижные опоры и одна неподвижная – крайняя. Подвижными опорами корпус при монтаже устанавливается на ролики, имеющие противоугонное устройство типа рейка-шестерня. К корпусу привариваются кронштейны для крепления механизмов подъёма крышки, штуцера для подвода пара, выпуска пара, выпуска конденсата и др. Внутри корпуса внизу укреплён рельсовый путь."},{"type":"text","text":"Крышка состоит из фланца и приваренного к нему встык эллиптического днища. Фланец крышки имеет зубья, которые сопрягаются с зубьями фланца корпуса при закрывании крышки. К днищу приваривается цапфа для соединения с рычагом механизма подъёма."},{"type":"text","text":"Механизм подъёма крышки включает в себя гидроцилиндр. Гидроцилиндр крепится к кронштейну механизма подъёма при помощи проушины. Шток гидроцилиндра проушиной соединяется с рычагом, который, поднимаясь или опускаясь, поднимает или опускает крышку автоклава. На кронштейне механизма подъёма закреплен хомут, который поворачивается на определённый угол гидроцилиндром и служит для фиксации крышки в поднятом положении. Крайнее положение крышки и хомута фиксируются конечными выключателями, расположенными на кронштейне механизма подъёма."},{"type":"text","text":"Гидроцилиндр поворота (байонет) - повороты крышки осуществляют два гидроцилиндра. Крайние положения крышки фиксируются конечными выключателями."},{"type":"text","text":"Система непрерывного отвода конденсата: из автоклава конденсат поступает по дренажному трубопроводу в грязевик. При входе потока конденсата в грязевик вследствие увеличения объёма скорость потока уменьшается, что способствует выпадению грубых частиц извести. Далее через фильтр грубой очистки конденсат поступает в ёмкость. Основная масса конденсата, образующаяся в начале запаривания, отводится через нижний штуцер грязевика по обводной байпасной линии и конденсатоотводчик. Включение обводной линии производится автоматически при помощи программы автоклавной обработки. Для этой цели на обводной линии установлен вентиль с электроприводом. При выходе на режим запаривания (горизонт), обводная линия закрывается, и сброс конденсата осуществляется через термодинамический конденсатоотводчик. Для выравнивания давления в паровых пространствах автоклава и конденсатной линии предусмотрена уравнительная линия. Автоклав оснащён водоуказательным стеклом."},{"type":"text","text":"Гидравлическая система с насосной станцией. Общая система гидропривода, рассчитанная для работы пяти автоклавов, обслуживается одной насосной станцией. Гидравлическая система с насосной станцией предназначена для подачи и распределения масла в гидроцилиндры механизмов подъёма крышки, поворота крышек, поворота хомутов, подъёма и опускания переходных мостиков. Насосная станция состоит из сварного бака с объёмом заливаемого масла 95 литров. Бак разделён перегородкой на сливную и нагнетательную линии. На крышке бака установлен лопастной насос НПЛ 8/16 УХЛ. На нагнетательном трубопроводе установлены предохранительный клапан для перепуска избытка масла, и клапан тормозной. Очистка масла, циркулирующего в системе, осуществляется пластинчатым фильтром и постоянным магнитом. На корпусе автоклава расположены две панели распределения, на которых смонтированы по 4 гидрораспределителя с электрическим управлением. Насос и гидравлическая аппаратура, установленная на насосной станции и распределительных панелях, работают на минеральном масле."},{"type":"text","text":"Устройство для контроля разности температур между верхней и нижней образующими корпуса автоклава включает две термопары, расположенные в средней части корпуса вверху и внизу. Разность температур не должна превышать 10 градусов."},{"type":"text","text":"Сигнально – блокировочное устройство (СБУ). Предназначено, чтобы обеспечить безопасную эксплуатацию автоклава и должно обеспечить:"},{"type":"text","text":"- невозможность впуска пропиточного состава в автоклав, когда крышки открыты или не полностью закрыты"},{"type":"text","text":"- невозможность открытия крышек при наличии в автоклаве давления пара свыше 0,004 Мпа и закрытом контрольном вентиле; сигнализацию, разрешающую открывание крышек при давлении в автоклаве менее 0,004 Мпа."},{"type":"text","text":"СБУ обеспечивает безопасную эксплуатацию наличием трёх цепей блокирования: механической, паровой и электрической. Цепь механического блокирования включает: фиксирующее устройство, подвижной шток СБУ и маховик контрольного вентиля. Цепь парового блокирования включает: мембранное реле давления, якорь которого при давлении в автоклаве более 0,004 МПа поднимается, входит в паз штока и фиксирует его. Цепь электрического блокирования включает два микропереключателя, установленных в крайних положениях штока СБУ и якоря реле давления. Микропереключатели через блокировочное реле включены вцепи электропривода задвижек впуска и выпуска пара, насосной станции и в световые табло. СБУ действует следующим образом: перед закрывание крышки необходимо закрыть задвижки впуска острого и перепускного пара; задвижки выпуска пара из автоклава на перепуск и в атмосферу. Крышку опустить, повернуть до полного зацепления зубьев. При этом положении должен сработать конечный выключатель, контролирующий закрытое положение крышки. Нажать на ручку и приподнять уголок, удерживающий шток в правом положении; шток под действием пружины переместиться влево, и конец штока займёт положение в отверстии сектора. Крышка зафиксирована. Необходимо закрыть контрольный вентиль. Загорается сигнальная лампа с надписью «Автоклав закрыт». Далее диспетчер запускает цикл запаривания в автоматическом режиме, открывается клапан «Пар под прокладку», затем открывается привод «Острый пар», в автоклав подаётся пар по уставке. При давлении в автоклаве более 0,004МПа якорь реле давления поднимается, замыкает микропереключатель, который через блокировочное реле зажигает сигнальную лампу «Автоклав под давлением» и запирает шток, что исключает возможность открывания крышки под давлением. Разблокировка крышки происходит в обратной последовательности. По окончания цикла запарки, после перекрытия задвижек впуска острого и перепускного пара, на перепуск и в атмосферу, когда давление на манометре «0», открывается контрольный вентиль. При достижении давления в автоклаве 0,004 МПа реле давления освободит шток, т.е. якорь опустится в нижнее положение и через микропереключатель реле давления и блокировочное реле потухнет сигнальная лампа «Автоклав под давлением». Нажимая на ручку, шток сместить вправо."},{"type":"text","text":"Мостик перекидной соединяет рельсовый путь автоклава с общезаводской системой рельсовых путей. Мостик состоит из подвижной рамы, на которой закреплены рельсы двух роликовых опор, неподвижной опорной рамы. Подъём и опускание подвижной рамы осуществляется гидроцилиндром."},{"type":"text","text":"Устройство автоматизированного управления технологическим процессом запаривания должно обеспечить заданную скорость разогрева корпуса автоклава и ведения технологического процесса в заданной программе. Устройство включает два регулирующих клапана на впуске и выходе пара под прокладку, задвижку на подаче острого пара, задвижку на подаче пара в автоклав по линии перепуска, задвижку на выход пара из автоклава по линии перепуска, задвижку на выход пара из автоклава в атмосферу, задвижку на вакуумирование автоклава, а также шкафы управления."},{"type":"text","text":"Устройство, фиксирующее для системы «Ключ-марка», состоит из пластины с приваренным к ней рычагом, в котором имеется прорезь. Рычаг поворачивается на кронштейне. При закрытой крышке (при 100% перекрытии зубьев крышки зубьями фланца корпуса) пластина вводится во впадину фланца корпуса, а в прорезь рычага входит кронштейн с отверстием, в которое навешивается замок."},{"type":"image","src":"images/doc2_044.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"СБУ автоклава"},{"type":"text","text":"Шкаф управления крышками автоклава."},{"type":"text","text":"Со стороны загрузки и выгрузки установлено по одному шкафу управления крышкой автоклава."},{"type":"image","src":"images/doc2_045.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Функции:"},{"type":"text","text":"Запуск гидростанции."},{"type":"text","text":"Автоматическое управление последовательностью открытия-закрытия крышек автоклава"},{"type":"text","text":"Возможность ручного управления системой гидрораспределителей для управления гидроцилиндрами."},{"type":"text","text":"Обработка, отображение аварий конечных выключателей"},{"type":"text","text":"Запись в энергонезависимую память контроллера аварийных ситуаций"},{"type":"text","text":"Программная и аппаратная блокировка запуска цикла запаривания при открытых крышках"},{"type":"text","text":"Запуск гидростанции может осуществляться как в ручном, так и в автоматическом режимах. Чтобы запустить гидростанцию в ручном режиме, нужно перевести переключатель с ключом «авто/ручн» в положение «ручн» и нажать кнопку зелёного цвета «пуск». Далее произойдёт запуск насосной станции с прерывистым звуковым сигналом. Для того, чтобы отключить насосную станцию, нужно нажать кнопку красного цвета. Чтобы запустить насосную станцию в автоматическом режиме, нужно перевести переключатель с ключом в положение «авто». Далее, в зависимости от того, что нужно сделать (открыть или закрыть крышку), выбираем соответствующую кнопку, нажимаем её и удерживаем до тех пор, пока не запустится насосная станция и не появится прерывистый звуковой сигнал. Это кнопки «пуск/откр» и «пуск/закр». Для того, чтобы насосная станция запустилась, нужно чтобы на контроллере не горела индикация красного цвета «запрет пуска». Если же наоборот, то смотрим, закрыты ли все электрические привода. Так же нужно проверить не нажата ли кнопка экстренной остановки красного цвета в виде грибка. Чтобы отжать её, нужно вставить ключ и повернуть его."},{"type":"text","text":"Автоматическое управление последовательностью открытия – закрытия крышек автоклава осуществляется тогда, когда переключатель с ключом «авто/ручн» находится в положении «авто». Рассмотрим пример, когда нам нужно закрыть автоклав в автоматическом режиме. Нажимаем и удерживаем кнопку «пуск/закр» до момента, когда запустится насосная станция и появится прерывистый звуковой сигнал. В первый момент должен опуститься трап. По сработке конечного выключателя на трапе (трап опущен) – поднимается крышка, срабатывает конечный выключатель (крышка поднята). После этого отводится хомут, срабатывает конечный выключатель (хомут отведён). Далее, когда хомут отведён, по сработке его конечного выключателя начинается опускание крышки. После сработки конечного выключателя (крышка опущена) начинается закрывание байонета до срабатывания его конечного выключателя (байонет закрыт)."},{"type":"text","text":"Ручное управление системой гидрораспределителей. Для этого необходимо запустить насосную станцию в ручном режиме (см. п.1.). На щите управления имеются соответствующие органы управления (кнопки со стрелочками): подъём и опускание мостика, ввод и отвод хомута, подъём и опускание крышки, закрытие и открытие байонета. В случае, если один из органов управления не работает, открытие или закрытие можно произвести, нажав на золотник гидрораспределителя."},{"type":"image","src":"images/doc2_046.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Обработка и отображение аварий конечных выключателей. Контроллер щита управления имеет функцию обработки и отображения положения концевых выключателей. Информация отображения положения выводится на табло контроллера, благодаря чему можно судить в каком положении находится концевой выключатель. Имеется три положения концевых выключателей: открыт, переход, закрыт. Если концевой выключатель неисправен, либо не сработал, то контроллер определяет неисправность выключателя. В этом случае на дисплее появится надпись «Авария» и на щите управления замигает лампа красного цвета «Авария», которая будет мигать."},{"type":"text","text":"Контроллер щита управления имеет свою энергонезависимую память, в которую записываются все неисправности. Чтобы просмотреть неисправности, нужно зайти в «журнал событий», нажав на клавишу «F3». Чтобы выйти, нужно нажать клавишу «Escape». Сброс аварии можно осуществить, нажав и удерживая клавишу «Stop»."},{"type":"text","text":"Имеется программная и аппаратная блокировки запуска цикла запаривания при открытых крышках. Аппаратная блокировка: её роль выполняет СБУ. Программная блокировка: на контроллер щита управления крышкой поступают сигналы о закрытии крышки. Это сигнал с микропереключателя СБУ (шток), сигналы с конечных выключателей крышки, трапа, хомута, байонета. Только после этого контроллер посылает сигнал на контроллер автоклавной обработки о закрытии крышек и готовности к запариванию."},{"type":"text","text":"Шкаф управления автоклавной обработкой."},{"type":"text","text":"Предназначен для управления циклом запаривания кирпича-сырца. Шкаф включает в себя: контроллер, сенсорную панель оператора, органы управления и индикации. Имеется переключатель с ключом «Авто/Ручн», с помощью которого можно переводить в ручной режим. Этот режим нужен в основном для открытия и закрытия электроприводов клапанов. Чтобы попасть в ручной режим, нужно ввести соответствующий пароль на панели оператора. Также имеется кнопка экстренной остановки цикла запаривания при возникновении аварийных ситуаций. Имеет форму грибка красного цвета с ключом. При её нажатии во время цикла запаривания закрываются все электропривода клапанов. Благодаря чему прекращается доступ пара в автоклав и из него. В составе этой системы имеются клапана с электроприводом: пар под прокладку, пар из-под прокладки, острый пар, пар из перепуска пар в перепуск, вакуумирование, сброс в атмосферу, сброс конденсата."},{"type":"text","text":"В щиты устанавливаются контроллеры двух видов - сенсорные и кнопочные. Не допускается управление контроллерами в грязных перчатках!!!!"},{"type":"image","src":"images/doc2_047.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Имеет функции:"},{"type":"text","text":"Управление циклом запаривания."},{"type":"text","text":"Управление электроприводами клапанов подачи и сброса пара как в ручном, так и в автоматическом режимах."},{"type":"text","text":"Подача и сброс пара в автоклав согласно заданной циклограмме."},{"type":"text","text":"Сбор показаний датчиков (датчики температуры верхней и нижней образующих, температуры внутри автоклава, давления в автоклаве)."},{"type":"text","text":"Управление, выдача в понятном виде человеку показаний датчиков на дисплее сенсорной панели оператора."},{"type":"text","text":"Реализация функции перепуска пара из одного автоклава в другой, что позволяет достичь экономии пара до 23%."},{"type":"text","text":"Обработка аварий в соответствии заданному алгоритму программы."},{"type":"text","text":"Управление циклом запаривания осуществляется с помощью программы «Scada». Эта программа имеет три этапа: подъём до необходимого давления, выдержка при набранном давлении, сброс пара. Все три этапа происходят по уставке и контролируются ею. В контроллере задаются специальные параметры: вакуумирование (если нужно), подъём давления до горизонта в два этапа, время подъёма до горизонта в два этапа, необходимое время выдержки на горизонте, время сброса давления в атмосферу, либо в перепуск. Управление запариванием для удобства осуществляется с рабочего места диспетчера."},{"type":"text","text":"В автоматическом режиме подъём и сброс пара осуществляется по уставке. В ручном же режиме нужно контролировать процент открытия острого пара и при сбросе в атмосферу либо в перепуск. Контроль можно осуществлять либо по циклограмме, либо по манометру."},{"type":"text","text":"При каждом запаривании диспетчер проверяет либо вносит новые параметры цикла запаривания."},{"type":"text","text":"На дисплее сенсорной панели шкафа управления и мониторе диспетчера отображаются все важные параметры цикла запаривания. А именно: давление и температура в автоклаве, температура верхней и нижней образующих автоклава. Для экономии пара можно использовать перепуск из автоклава в автоклав. Это позволяет сэкономить до 23% теплоносителя, что в свою очередь позволит снизить затраты на производство."},{"type":"text","text":"Все аварийные сбои, неисправности программа записывает в журнал событий. Все аварии и ошибки сбрасываются на контроллере. Для этого нужно нажать на нём красную кнопку «стоп» и удерживать её. Контроллер так же имеет свою энергонезависимую память для записи аварий и ошибок."},{"type":"text","text":"Применяются контроллеры кнопочного и сенсорного типов."},{"type":"text","text":"Управление приводами в ручном режиме:"},{"type":"text","text":"- переводим ключом управление щита в положение «ручн»"},{"type":"text","text":"- в нижнем левом углу панели нажимаем на иконку «доступ»"},{"type":"text","text":"- появится окно ввода данных"},{"type":"text","text":"- в верхней строке нажатием выбираем «старший оператор»"},{"type":"text","text":"- в следующей строке вводим пароль «456»"},{"type":"text","text":"- в следующем пункте выбираем «класс доступа В»"},{"type":"text","text":"- повторным нажатием на «доступ» это меню сворачивается"},{"type":"text","text":"- в верхнем левом углу панели нажимаем на иконку «меню»"},{"type":"text","text":"- выбираем «управление»"},{"type":"text","text":"- открываем крышку щита и переводим флажок реле Q1 в вертикальное положение (крайнее левое), закрываем крышку щита"},{"type":"text","text":"- у каждого привода имеется индикация управления «откр» и «закр»."},{"type":"text","text":"- при нажатии будет слышен звуковой сигнал, удерживаем некоторое время пока индикация не поменяет цвет"},{"type":"text","text":"- на рисунке ниже видно состояние привода – переход. В это время привод находится в стадии закрытия или открытия. При закрытом или открытом положении будет соответствующая надпись в центре."},{"type":"text","text":"- одновременно можно управлять только одним приводом"},{"type":"text","text":"- после управления выходим из меню"},{"type":"text","text":"- переводим флажок реле Q1 в щите в горизонтальное положение, переводим ключ на крышке щита в положение «авто»"},{"type":"image","src":"images/doc2_048.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc2_049.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Сенсорный контроллер"},{"type":"text","text":"Не допускается управление сенсорным контроллером грязными руками и перчатками. Навигация осуществляется кнопками, а изменение параметров и пароль сенсором."},{"type":"text","text":"Перепуски из автоклавов"},{"type":"text","text":"Перед началом каждого цикла запаривания оператор должен перезагрузить автоклав после настройки циклограммы. Для этого нужно открыть щит управления и отключить автоматы QF1, QF2 в верхнем левом углу щита примерно на одну минуту. Первый автомат отключает питание контроллера щита управления, второй – питание щитов крышек автоклавов."},{"type":"text","text":"Для того, чтобы появилась уставка для перехода на подъём с острого пара, нужно чтобы давления в автоклаве приёмнике сравнялось с давлением в автоклаве источнике. При переходе работы на острый пар для предотвращения провала давления в магистрали пара, привод острого пара должен открываться не более чем на 20 процентов. Для это в меню «настройки» контроллера имеется параметр его процента открытия, который может изменяться."},{"type":"text","text":"Для появления уставки сброса остаточного давления из автоклава источника, нужно чтобы давления в автоклаве приёмнике было примерно на 0,2 атмосферы больше. В меню цикла запаривания «сброс пара» на мониторе оператора появится иконка «сброс пара». При её нажатии появиться уставка сброса остаточного давления из автоклава источника. В этот момент откроется привод на байпасной линии сброса конденсата на определённый процент, который также можно выставить в меню «настройки» контроллера в разделе «продувка»."},{"type":"image","src":"images/doc2_050.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Шкаф управления вакуумным насосом."},{"type":"text","text":"Шкаф управляет работой вакуумного насоса, который в свою очередь создаёт в автоклаве отрицательное давление. Шкаф имеет свой контроллер, органы управления и индикации. Имеется переключатель «Авто/Ручн», что позволяет работать в ручном режиме, либо в автоматическом. Также имеется кнопка экстренной остановки «Stop» красного цвета в виде грибка."},{"type":"image","src":"images/doc2_051.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Функции шкафа:"},{"type":"text","text":"Запуск этапа вакуумирования дистанционно с подсистемы автоклавной обработки."},{"type":"text","text":"Запуск этапа вакуумирования вручную из шкафа управления вакуумным насосом."},{"type":"text","text":"Обработка аварий подсистемы вакуумного насоса."},{"type":"text","text":"Запись аварийных ситуаций в энергонезависимую память контроллера."},{"type":"image","src":"images/doc2_052.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"К вакуумному насосу подводится вода. Без неё работать не будет. Так же имеется сливной бак. Вся запорная арматура должна находиться в открытом состоянии."},{"type":"text","text":"Запуск этапа вакуумирования происходит в случае: если в контроллере автоклавной обработки выбрана эта функция. Вакуумирование включается после того, как откроется клапан «пар под прокладку» и клапан «вакуумирование». Весь процесс вакуумирования занимает около 10 минут."},{"type":"text","text":"Чтобы запустить вакуумирование вручную, нужно перевести переключатель «авто/ручн» в положение «ручн» и нажать кнопку «пуск». Для этого необходимо, чтобы клапан «вакуумирование» был открыт. Выключаем тогда, когда в автоклаве будет соответствующее давление (-0.05 МПа), нажав кнопку «стоп». Диспетчер контролирует весь процесс с помощью данных на экране контроллера."},{"type":"text","text":"Сброс аварий осуществляется с помощью красной кнопки «стоп» на панели контроллера. Список аварий можно посмотреть в журнале событий, нажав клавишу «F3». Для этого в контроллере есть энергонезависимая память."},{"type":"text","text":"Шкафы управления насосными станциями."},{"type":"text","text":"Предназначены для управления насосной станцией, созданием давления гидравлической жидкости и её распределения. Может работать в автоматическом режиме и местном, т.е. включаться оператором непосредственно с щита. Для этого имеются соответствующие органы управления."},{"type":"image","src":"images/doc2_053.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Функции:"},{"type":"text","text":"Включение и выключение масляного насоса и поддержания оптимального давления масла в гидравлической системе."},{"type":"text","text":"Включение необходимого электромагнитного гидрораспределителя, направляющего гидравлическое масло в автоклав."},{"type":"text","text":"Включение и выключение насосной станции происходит при открытии или закрытии крышки автоклава в автоматическом, либо ручном режимах. Сигнал на включение насосной станции подаётся с блока управления крышками автоклава. В свою очередь насосная станция поддерживает оптимальное рабочее давление."},{"type":"text","text":"Имеется сеть гидрораспределителей (4 штуки на 4 автоклава), которые подают давление на определённый автоклав."},{"type":"image","src":"images/doc2_054.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Так же имеется контрольный щуп для проверки уровня масла в баке станции."},{"type":"text","text":"В начале смены оператор обязан проверить уровень масла в баках при помощи щупа и смотрового стекла."},{"type":"text","text":"Шкафы управления конденсатными насосами."},{"type":"text","text":"Управляют конденсатными насосами, которые откачивают конденсат из бака."},{"type":"image","src":"images/doc2_055.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc2_056.png","alt":"Иллюстрация из исходного документа"},{"type":"image","src":"images/doc2_057.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Щиты управления насосами №1 и №2"},{"type":"image","src":"images/doc2_058.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Поплавковый датчик уровня конденсата в баке"},{"type":"image","src":"images/doc2_059.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Рабочий насос №1."},{"type":"text","text":"Насосы установлены в приямке в количестве двух штук. Под рабочим насосом №1 установлен поплавковый датчик, сигнал с которого поступает на пульт сигнализации в диспетчерской. Датчик срабатывает по определённому уровню воды, чтобы не затопило насосы."},{"type":"image","src":"images/doc2_060.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Запасной насос №2"},{"type":"text","text":"Один из них рабочий, другой запасной. Рабочим насосом управляет щит №1 как в ручном, так и в автоматическом режиме. Запасной насос управляется от щита №2 только в ручном режиме, авторежим не работает. Допускается использовать насосы в паре, если один не справляется как в ручном, так и в авторежиме. Работа рабочего насоса осуществляется щитом №1 с помощью блока автоматики с поплавковым уровнем конденсата в баке, который включает в себя поплавок и два датчика верхнего и нижнего уровня. На запасном насосе запорная арматура должна быть в закрытом положении. Каждый насос имеет свой шкаф управления. На каждом шкафе имеется переключатель режима работы: автоматический и ручной. В ручном режиме насос будет работать постоянно, а в автоматическом по наличию конденсата в баке. При использовании насосов в паре в авторежиме, нужно на щите №1 и щите №2 переключить переключатели в режим «авто». Отдельно запасной насос управляется щитом №2 и может работать только в ручном режиме. Откачиваемый конденсат подаётся в накопительные ёмкости, которые установлены за котельной. Далее этот конденсат подаётся на производство."},{"type":"text","text":"На баке с конденсатом установлен поплавковый датчик уровня, который включает в себя поплавок, датчик нижнего и верхнего уровней."},{"type":"text","text":"Расположение и название клапанов с электроприводами."},{"type":"image","src":"images/doc2_061.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Электропривода на эстакаде"},{"type":"image","src":"images/doc2_062.png","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"Электропривод на конденсатной линии"},{"type":"text","text":"Клапан сброса пара из-под прокладки."},{"type":"text","text":"Клапан подачи пара под прокладку"},{"type":"text","text":"Клапан острого пара. Пар поступает из магистрали."},{"type":"text","text":"Клапан пара из перепуска. Пар поступает из определённого автоклава."},{"type":"text","text":"Клапан сброса пара в перепуск."},{"type":"text","text":"Клапан вакуумирования."},{"type":"text","text":"Клапан сброса пара в атмосферу."},{"type":"text","text":"Клапан сброса конденсата из автоклава."},{"type":"text","text":"Перед каждым клапаном с электроприводом установлена запорная арматура. После каждого цикла запаривания она должна находиться в закрытом положении в целях безопасности."},{"type":"text","text":"С помощью запорной арматуры не сложно определить соответствующий трубопровод. Трубопровод острого пара и перепуска утеплены для уменьшения теплопотерь."},{"type":"text","text":"41. Запаривание цветного, лицевого и рядового кирпича."},{"type":"text","text":"42. Запаривание рядового кирпича"},{"type":"text","text":"Производится с помощью определённой циклограммы."},{"type":"text","text":"Перед загрузкой сырца проверить состояние защитных листов и козырьков. (Особенно после замены резины)."},{"type":"text","text":"Произвести закрытие крышки автоклава согласно пункту 15 (стр. 13)."},{"type":"text","text":"Запаривание осуществляется с перепуска для экономии пара. В особых случаях допускается запаривать с острого пара после простоев, когда нет источника пара из другого автоклава."},{"type":"text","text":"Отключить участие конденсатоотводчика №4 на линии сброса конденсата. Для этого перекрываем вентиль «отключение конденсатоотводчика» №1 после грязевика №9."},{"type":"text","text":"Смотрим по переключателю режимов, чтобы электропривод №8 был в авторежиме. Такой переключатель имеют привода, установленные на автоклавах №1 -… №5 включительно. На автоклавах №6, №7, №8 установлены привода без переключателя. При этом верхняя вращающаяся фишка жёлтого цвета не должна вращаться при попытке открыть или закрыть привод вручную. Если же фишка легко вращается (это ручной режим управления приводом), то переключаем привод. Если привод находится в ручном режиме, то мы не сможем им управлять с панели оператора щита управления."},{"type":"text","text":"В контроллере щита управления в меню настроек должна быть включена продувка. Далее настраиваем параметры работы привода. Привод откроется при превышении допустимой разницы температур между верхней и нижней образующими автоклава. В конце цикла после перепуска или сброса пара в атмосферу привод откроется на определённый процент для сброса остатков конденсата."},{"type":"text","text":"Смотрим, чтобы был открыт вентиль «отключение конденсатоотводчика» №2 после привода около главной трубы сброса конденсата из автоклавов в бак."},{"type":"text","text":"Управление сбросом конденсата осуществляется по проценту открытия привода, времени открытия, разнице между образующими автоклава."},{"type":"text","text":"Если температура нижней образующей не поднимается в нужный диапазон (он настраивается), то идём смотреть линию конденсата. Если всё сделано правильно, то программно в меню увеличиваем время открытия привода."},{"type":"text","text":"Параметры продувки в меню контроллера:"},{"type":"text","text":"- давление продувки"},{"type":"text","text":"- время продувки"},{"type":"text","text":"- разница температур верхней и нижней образующих"},{"type":"text","text":"- процент открытия привода"},{"type":"text","text":"- время паузы, при котором будет открыт привод"},{"type":"text","text":"- процент открытия привода при сбросе пара в конце цикла"},{"type":"text","text":"- раздел «продувка» в меню «настройки» должен быть включён"},{"type":"text","text":"Произвести запаривание – подъем на горизонт, поддержание давления на горизонте, выдержка – автоклава."},{"type":"text","text":"По окончании выдержки осуществить сброс пара в перепуск, затем – в атмосферу. Остаток конденсата слить в автоматическом режиме (при неоткрытие – в ручном) в конденсатный бак."},{"type":"text","text":"Открыть крышку согласно п. 15 (стр. 13). В момент открытия крышки присутствовать около крышки, убедиться, что ничего не мешает открытию крышки."},{"type":"text","text":"После открытия крышки автоклава сразу провести осмотр состояния защитных листов и осмотр кирпича на стороне загрузки."},{"type":"text","text":"После удаления кирпича из автоклава произвести осмотр внутренней части с помощью фонаря. Особо обратить внимание на защитные листы около выгрузки, а также на поддон для сбора конденсата в середине автоклава."},{"type":"text","text":"Произвести чистку автоклава согласно п. 32 данной инструкции."},{"type":"text","text":"43. Запаривание цветного и лицевого кирпича"},{"type":"text","text":"Производится с помощью определённой циклограммы."},{"type":"text","text":"Перед загрузкой сырца проверить состояние защитных листов и козырьков. (Особенно после замены резины)."},{"type":"text","text":"Произвести закрытие крышки автоклава согласно пункту 15 (стр. 13)."},{"type":"text","text":"Открываем вентиль «отключение конденсатоотводчика» №1 после грязевика."},{"type":"text","text":"Электропривод №8 должен находиться в авторежиме на автоклавах с №1 по №5 включительно."},{"type":"text","text":"Вентиль «отключение конденсатоотводчика» №2 у главной трубы конденсата должен быть в открытом положении."},{"type":"text","text":"Настраиваем параметры работы привода в контроллере щита управления."},{"type":"text","text":"Сброс конденсата происходит с помощью конденсатоотводчика во всём цикле запаривания. Привод №8 не участвует в работе до момента остаточного сброса давления из автоклава. Этот параметр настраивается в меню контроллера. Если же разница между образующими сильно растёт, то смотрим открыты ли вентиля №1 и №2. Перед запариваем автоклав должен быть почищен."},{"type":"text","text":"Произвести запаривание – подъем на горизонт, поддержание давления на горизонте, выдержка – автоклава."},{"type":"text","text":"Перед каждым открытием автоклава смотрим в смотровое стекло №3 на уравнительной линии на наличие конденсата во избежание затопления зоны загрузки. Расположена выше грязевика №9. Для этого нужно чтобы вентиля «отключение указателя уровня конденсата» №5 и «уравнительная линия» №6 были открыты. Вся арматура обвязки автоклава имеет таблички с названиями."},{"type":"text","text":"Управление приводом конденсата разрешается только с сенсорной панели щита управления. В конце цикла, когда пар сбросился, оператор спускается к смотровому стеклу. Если присутствует конденсат, оператор поднимается к щиту управления автоклава, входит в ручное меню управления приводами и открывает его. После полного сброса конденсата разрешается открыть автоклав. Открытие привода механическим способом запрещается!!!!"},{"type":"text","text":"Открыть крышку согласно п. 15 (стр. 13). В момент открытия крышки присутствовать около крышки, убедиться, что ничего не мешает открытию крышки."},{"type":"text","text":"После открытия крышки автоклава сразу провести осмотр состояния защитных листов и осмотр кирпича на стороне загрузки."},{"type":"text","text":"После удаления кирпича из автоклава произвести осмотр внутренней части с помощью фонаря. Особо обратить внимание на защитные листы около выгрузки, а также на поддон для сбора конденсата в середине автоклава."},{"type":"text","text":"Произвести чистку автоклава согласно п. 32 данной инструкции."},{"type":"text","text":"44. Конденсатная линия автоклава."},{"type":"image","src":"images/doc2_063.jpeg","alt":"Иллюстрация из исходного документа"},{"type":"text","text":"№1 - вентиль «отключение конденсатоотводчика» после грязевика №9"},{"type":"text","text":"№2 - вентиль «отключение конденсатоотводчика» у главной трубы конденсата"},{"type":"text","text":"№3 – смотровое стекло наличия конденсата в автоклаве"},{"type":"text","text":"№4 – конденсатоотводчик"},{"type":"text","text":"№5 - вентиль «отключение указателя уровня конденсата»"},{"type":"text","text":"№6 – вентиль «уравнительная линия»"},{"type":"text","text":"№7 – обратный клапан"},{"type":"text","text":"№8 – привод конденсата на байпасной линии"},{"type":"text","text":"№9 – грязевик"},{"type":"text","text":"№10 – байпасная линия с приводом"},{"type":"text","text":"№11 – сетчатый фильтр"},{"type":"text","text":"№12 – манометр после сетчатого фильтра"},{"type":"text","text":"№13 – манометр до сетчатого фильтра"},{"type":"text","text":"№14 – вентиль «продувка указателя уровня конденсата»"},{"type":"text","text":"№15 – труба продувки указателя уровня конденсата"},{"type":"text","text":"№16 - главная труба сброса конденсата из автоклавов"},{"type":"text","text":"45. Обязанности оператора"},{"type":"text","text":"1. Уметь работать на должности диспетчера, оператора РТС"},{"type":"text","text":"2. По распоряжению руководителя службы совмещать вышеперечисленные должности в связи с производственной необходимостью"},{"type":"text","text":"3. Дежурства в праздничные дни:"},{"type":"text","text":"- обход территории завода и котельной каждый час"},{"type":"text","text":"- выключать не нужное освещение"},{"type":"text","text":"- закрывать все двери и ворота"},{"type":"text","text":"- в зимнее время проверять работу воздушной завесы в пескоприёмнике, батареи отопления, закрытие дефлекторов над автоклавами"},{"type":"text","text":"- быть на связи с охраной по рации"},{"type":"text","text":"4. Приборка и обдувка зон автоклавов согласно графику"},{"type":"text","text":"5. Продувка блока кондиционера у диспетчерской согласно графику"},{"type":"text","text":"6. Чистка автоклава перед каждым запариванием"},{"type":"text","text":"7. Протирание перил эстакады автоклавов в начале каждой дневной смены"},{"type":"text","text":"8. Ведение производственных журналов"}]};
